mapper.select:
SELECT COUNT(*) FROM digital_team_project_skill
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND skill_id = #{skillId}

mapper.update:
UPDATE digital_team_project_skill SET enabled = #{enabled},
updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND skill_id = #{skillId}

mapper.delete:
DELETE FROM digital_team_project_skill
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND skill_id = #{skillId}
